arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-b2e78bf721ff4b27a72e001674d4f01f/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`. It has two projects:

- **ShipmentTracker** (server): hosts the app, has EF Core + Identity configured with SQLite
- **ShipmentTracker.Client** (WebAssembly): all interactive components go here

**CRITICAL ARCHITECTURE RULES (Auto Global mode):**
- Interactive components MUST go in the `.Client` project
- Components in `.Client` CANNOT access DbContext or server-only services
- Data access from .Client must go through HTTP APIs
- Both Program.cs files must register matching service interfaces
- No `@rendermode` needed on individual pages (global mode handles it)
- Identity/Account pages are static SSR — don't touch them

## What to implement

### 1. Shared Models (in .Client project — both projects can reference it)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class ShipmentSummary
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime ShippedDate { get; set; }
    public string RecipientName { get; set; } = string.Empty;
}

public class ShipmentDetail : ShipmentSummary
{
    public string SenderName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string Notes { get; set; } = string.Empty;
    public List<TrackingEvent> TrackingEvents { get; set; } = [];
}

public class TrackingEvent
{
    public int Id { get; set; }
    public DateTime Timestamp { get; set; }
    public string Location { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
}
```

### 2. Service Interface (in .Client project)

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentSummary>> GetShipmentsAsync();
    Task<ShipmentDetail?> GetShipmentByIdAsync(int id);
    Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateStatusAsync(int id, ShipmentStatus newStatus);
}
```

### 3. Client-side Implementation (in .Client project)

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs` — calls server APIs via HttpClient:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync()
    {
        return await httpClient.GetFromJsonAsync<List<ShipmentSummary>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await httpClient.GetFromJsonAsync<ShipmentDetail?>($"api/shipments/{id}");
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await httpClient.GetFromJsonAsync<ShipmentDetail?>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        await httpClient.PostAsJsonAsync($"api/shipments/{id}/status", newStatus);
    }
}
```

### 4. Server-side Data Entities

Create `ShipmentTracker/Data/ShipmentEntity.cs`:
```csharp
namespace ShipmentTracker.Data;

public class ShipmentEntity
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public int Status { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime ShippedDate { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string SenderName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string Notes { get; set; } = string.Empty;
    public List<TrackingEventEntity> TrackingEvents { get; set; } = [];
}

public class TrackingEventEntity
{
    public int Id { get; set; }
    public int ShipmentEntityId { get; set; }
    public ShipmentEntity Shipment { get; set; } = null!;
    public DateTime Timestamp { get; set; }
    public string Location { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Status { get; set; }
}
```

### 5. Update ApplicationDbContext

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();
    public DbSet<TrackingEventEntity> TrackingEvents => Set<TrackingEventEntity>();
}
```

### 6. Server-side Service Implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (ShipmentStatus)s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                ShippedDate = s.ShippedDate,
                RecipientName = s.RecipientName
            })
            .ToListAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await GetDetail(db.Shipments.Where(s => s.Id == id));
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await GetDetail(db.Shipments.Where(s => s.TrackingNumber == trackingNumber));
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is null) return;

        entity.Status = (int)newStatus;
        db.TrackingEvents.Add(new TrackingEventEntity
        {
            ShipmentEntityId = id,
            Timestamp = DateTime.UtcNow,
            Location = entity.Destination,
            Description = $"Status changed to {newStatus}",
            Status = (int)newStatus
        });
        await db.SaveChangesAsync();
    }

    private static async Task<ShipmentDetail?> GetDetail(IQueryable<ShipmentEntity> query)
    {
        return await query
            .Include(s => s.TrackingEvents)
            .Select(s => new ShipmentDetail
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (ShipmentStatus)s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                ShippedDate = s.ShippedDate,
                RecipientName = s.RecipientName,
                SenderName = s.SenderName,
                WeightKg = s.WeightKg,
                Notes = s.Notes,
                TrackingEvents = s.TrackingEvents
                    .OrderByDescending(e => e.Timestamp)
                    .Select(e => new TrackingEvent
                    {
                        Id = e.Id,
                        Timestamp = e.Timestamp,
                        Location = e.Location,
                        Description = e.Description,
                        Status = (ShipmentStatus)e.Status
                    })
                    .ToList()
            })
            .FirstOrDefaultAsync();
    }
}
