        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is null)
            notFound = true;
        else
            newStatus = shipment.Status;
    }

    private async Task UpdateStatus()
    {
        isUpdating = true;
        updateMessage = null;

        try
        {
            await ShipmentService.UpdateStatusAsync(Id, newStatus);
            shipment = await ShipmentService.GetShipmentByIdAsync(Id);
            updateMessage = $"Status updated to {newStatus}.";
        }
        catch
        {
            updateMessage = "Failed to update status. Please try again.";
        }
        finally
        {
            isUpdating = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
