@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<div class="container mt-4">
    <h1>📋 Shipments Dashboard</h1>

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filters.</div>
    }
    else
    {
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.RecipientName</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <a href="shipments/@s.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>

        <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
    }
</div>

@code {
    private List<ShipmentSummary>? shipments;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<ShipmentSummary> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments/{Id:int}"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Shipment Details</PageTitle>

<div class="container mt-4">
    @if (shipment is null && !notFound)
    {
        <p><em>Loading...</em></p>
    }
    else if (notFound)
    {
        <div class="alert alert-warning">Shipment not found.</div>
        <a href="shipments" class="btn btn-secondary">Back to Dashboard</a>
    }
    else
    {
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h1>Shipment @shipment!.TrackingNumber</h1>
            <a href="shipments" class="btn btn-outline-secondary">← Back</a>
        </div>

        <div class="row">
            <div class="col-md-6">
                <div class="card mb-3">
                    <div class="card-header"><strong>Shipment Info</strong></div>
                    <div class="card-body">
                        <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></p>
                        <p><strong>Origin:</strong> @shipment.Origin</p>
                        <p><strong>Destination:</strong> @shipment.Destination</p>
                        <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        <p><strong>Weight:</strong> @shipment.WeightKg kg</p>
                        @if (!string.IsNullOrEmpty(shipment.Notes))
                        {
                            <p><strong>Notes:</strong> @shipment.Notes</p>
                        }
                    </div>
                </div>
            </div>
            <div class="col-md-6">
                <div class="card mb-3">
                    <div class="card-header"><strong>People</strong></div>
                    <div class="card-body">
                        <p><strong>Sender:</strong> @shipment.SenderName</p>
                        <p><strong>Recipient:</strong> @shipment.RecipientName</p>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-header"><strong>Update Status</strong></div>
                    <div class="card-body">
                        <div class="input-group">
                            <select class="form-select" @bind="newStatus">
                                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@s">@s</option>
                                }
                            </select>
                            <button class="btn btn-primary" @onclick="UpdateStatus" disabled="@isUpdating">
                                @if (isUpdating)
                                {
                                    <span class="spinner-border spinner-border-sm me-1"></span>
                                }
                                Update
                            </button>
                        </div>
                        @if (updateMessage is not null)
                        {
                            <div class="alert alert-success mt-2 mb-0">@updateMessage</div>
                        }
                    </div>
                </div>
            </div>
        </div>

        @if (shipment.TrackingEvents.Count > 0)
        {
            <h4 class="mt-3">Tracking History</h4>
            <table class="table table-sm table-striped">
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Location</th>
                        <th>Status</th>
                        <th>Details</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var evt in shipment.TrackingEvents)
                    {
                        <tr>
                            <td>@evt.Timestamp.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>@evt.Location</td>
                            <td><span class="badge @GetStatusBadgeClass(evt.Status)">@evt.Status</span></td>
                            <td>@evt.Description</td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private ShipmentDetail? shipment;
    private bool notFound;
    private ShipmentStatus newStatus;
    private bool isUpdating;
    private string? updateMessage;

    protected override async Task OnInitializedAsync()
    {
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is null)
            notFound = true;
        else
            newStatus = shipment.Status;
    }

    private async Task UpdateStatus()
    {
        isUpdating = true;
        updateMessage = null;

        try
        {
            await ShipmentService.UpdateStatusAsync(Id, newStatus);
            shipment = await ShipmentService.GetShipmentByIdAsync(Id);
            updateMessage = $"Status updated to {newStatus}.";
        }
        catch
        {
            updateMessage = "Failed to update status. Please try again.";
        }
        finally
        {
            isUpdating = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

