```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (ShipmentStatus)s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                ShippedDate = s.ShippedDate,
                RecipientName = s.RecipientName
            })
            .ToListAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await GetDetail(db.Shipments.Where(s => s.Id == id));
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await GetDetail(db.Shipments.Where(s => s.TrackingNumber == trackingNumber));
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is null) return;

        entity.Status = (int)newStatus;
        db.TrackingEvents.Add(new TrackingEventEntity
        {
            ShipmentEntityId = id,
            Timestamp = DateTime.UtcNow,
            Location = entity.Destination,
            Description = $"Status changed to {newStatus}",
            Status = (int)newStatus
        });
        await db.SaveChangesAsync();
    }

    private static async Task<ShipmentDetail?> GetDetail(IQueryable<ShipmentEntity> query)
    {
        return await query
            .Include(s => s.TrackingEvents)
            .Select(s => new ShipmentDetail
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (ShipmentStatus)s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                ShippedDate = s.ShippedDate,
                RecipientName = s.RecipientName,
                SenderName = s.SenderName,
                WeightKg = s.WeightKg,
                Notes = s.Notes,
                TrackingEvents = s.TrackingEvents
                    .OrderByDescending(e => e.Timestamp)
                    .Select(e => new TrackingEvent
                    {
                        Id = e.Id,
                        Timestamp = e.Timestamp,
                        Location = e.Location,
                        Description = e.Description,
                        Status = (ShipmentStatus)e.Status
                    })
                    .ToList()
            })
            .FirstOrDefaultAsync();
    }
}
```

