api.MapGet("", async (IShipmentService svc) => await svc.GetShipmentsAsync());
api.MapGet("{id:int}", async (int id, IShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByIdAsync(id);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});
api.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
{
