    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});
api.MapPost("{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService svc) =>
{
    await svc.UpdateStatusAsync(id, newStatus);
    return Results.Ok();
});

